import re

def parse_duration(s):
    """Parse duration string like '1h30m', '45s', '1h' into total seconds."""
    if not s or not s.strip():
        return 0

    s = s.strip().lower()

    total = 0

    # Match and extract each component
    for match in re.finditer(r'(\d+)\s*(h|m|s)', s):
        value = int(match.group(1))
        unit = match.group(2)

        if unit == 'h':
            total += value * 3600
        elif unit == 'm':
            total += value * 60
        elif unit == 's':
            total += value

    return total
